import os, sys, tempfile, socket
for key in list(os.environ):
    if any(token in key.upper() for token in ('MYSQL', 'MONGO', 'POSTGRES', 'DATABASE', 'REDIS', 'PROXY')):
        os.environ.pop(key, None)
for key in ('CODE_ASSIST_ENDPOINT', 'ANTIGRAVITY_API_URL', 'RESOURCE_MANAGER_API_URL', 'SERVICE_USAGE_API_URL', 'GOOGLEAPIS_PROXY_URL', 'OAUTH_PROXY_URL', 'KEEPALIVE_URL'):
    os.environ[key] = 'http://127.0.0.1:9'
os.environ['ENABLE_LOG'] = '0'
os.environ['SMART_429_PROTECTION_ENABLED'] = '0'
os.environ['PYTHONDONTWRITEBYTECODE'] = '1'
sys.dont_write_bytecode = True
connect, connect_ex, getaddrinfo = socket.socket.connect, socket.socket.connect_ex, socket.getaddrinfo
def allowed(address):
    if isinstance(address, tuple) and address[0] not in ('127.0.0.1', '::1', 'localhost'):
        raise AssertionError('External test network is forbidden')
def guarded_connect(self, address):
    allowed(address)
    return connect(self, address)
def guarded_connect_ex(self, address):
    allowed(address)
    return connect_ex(self, address)
def guarded_addr(host, *args, **kwargs):
    if host not in ('127.0.0.1', '::1', 'localhost', None):
        raise AssertionError('External test DNS is forbidden')
    return getaddrinfo(host, *args, **kwargs)
socket.socket.connect, socket.socket.connect_ex, socket.getaddrinfo = guarded_connect, guarded_connect_ex, guarded_addr
with tempfile.TemporaryDirectory(prefix='mr-stream-tests-') as isolated:
    os.environ['CREDENTIALS_DIR'] = os.path.join(isolated, 'credentials')
    os.makedirs(os.environ['CREDENTIALS_DIR'])
    import pytest
    print('Python', sys.version.split()[0], 'cwd', os.getcwd())
    raise SystemExit(pytest.main(['-q', '--basetemp', os.path.join(isolated, 'pytest'), *sys.argv[1:]]))
